(1, 'Ambulance Fabrication', 'truck', 'services/ambulance.png', 'High-quality interior fabrication for all types of ambulances, including Basic Life Support (BLS) and Advanced Life Support (ALS) units. Features include custom oxygen manifolds, cabinetry & storage solutions, and electrical & lighting systems.', 1, '2026-04-23 06:14:00', '2026-04-23 06:14:00'),
(2, 'O.T Doors Fabrication', 'door-open', 'services/ot_doors.png', 'Hermetically sealed and non-hermetic doors designed specifically for Operation Theaters, ensuring sterility and air pressure control. Lead-lined for X-Ray rooms and automatic sliding options available.', 1, '2026-04-23 06:14:00', '2026-04-23 06:14:00'),
(3, 'Oxygen Panel & Pipeline', 'layers', 'services/oxygen_panel.png', 'Complete Medical Gas Pipeline System (MGPS) installation for ICU rooms, including bed head panels and alarm systems. Features centralized gas control and leak-proof copper piping.', 1, '2026-04-23 06:14:00', '2026-04-23 06:14:00'),
(4, 'ICU Curtains Fabrications', 'layout-grid', 'services/icu_curtains.png', 'Hospital privacy cubicle curtains and track systems, manufactured with medical-grade, antimicrobial fabrics. Flame retardant and tear-resistant mesh integrated.', 1, '2026-04-23 06:14:00', '2026-04-23 06:14:00'),
(5, 'Refurbished Equipments', 'refresh-cw', 'services/refurbished.png', 'Cost-effective refurbished hospital machines and equipment, fully tested and certified for safe medical use. Includes monitors, ventilators, and ICU beds with warranty.', 1, '2026-04-23 06:14:00', '2026-04-23 06:14:00');

