INSERT INTO `testimonials` (`id`, `name`, `role`, `content`, `image`, `created_at`, `updated_at`) VALUES
(1, 'Dr. Rajesh Patel', 'Senior Surgeon, Apollo Hospitals', 'High-quality medical furniture that meets international standards. Their ICU beds have been extremely reliable in our facility for over 5 years.', NULL, '2026-04-23 04:02:39', '2026-04-23 04:02:39'),
(2, 'Sarah Jenkins', 'Hospital Administrator, Grace Health', 'Excellent service and fast delivery. The factory-direct pricing saved us significantly on our recent hospital renovation project without compromising on quality.', NULL, '2026-04-23 04:02:39', '2026-04-23 04:02:39'),
(3, 'Amit Mishra', 'Founder, City Care Clinic', 'The engineering and durability of A One Hospicare equipment is top-notch. Highly recommended for institutional setups looking for long-term reliability.', NULL, '2026-04-23 04:02:39', '2026-04-23 04:02:39'),
(4, 'Dr. Megha Sharma', 'Chief of Medicine, Fortis Healthcare', 'Their specialized patient care beds have significantly improved patient comfort in our wards. The ABS panels are very easy to sanitize and maintain.', NULL, '2026-04-23 04:02:39', '2026-04-23 04:02:39');

